@@ -0,0 +1,89 @@
+/*
+ * SPDX-License-Identifier: Apache-2.0
+ *
+ * The OpenSearch Contributors require contributions made to this file be
+ * licensed under the Apache License, Version 2.0 (the "License"); you may
+ * not use this file except in compliance with the License.
+ */
+package org.opensearch.audit;
+
+import org.apache.logging.log4j.LogManager;
+import org.apache.logging.log4j.Logger;
+import org.opensearch.common.settings.Settings;
+import org.opensearch.transport.TransportRequest;
+
+import java.time.Instant;
+import java.util.Objects;
+
+/**
+ * Records audit events for search, get, index, and delete operations.
+ * Controlled by {@link AuditConfig}. All events are written to the
+ * dedicated audit appender configured in log4j2.properties.
+ */
+public class AuditLogger {
+
+    private static final Logger auditLog = LogManager.getLogger("audit");
+    private final AuditConfig config;
+
+    public AuditLogger(AuditConfig config) {
+        this.config = Objects.requireNonNull(config, "config must not be null");
+    }
+
+    public static AuditLogger fromSettings(Settings settings) {
+        return new AuditLogger(AuditConfig.fromSettings(settings));
+    }
+
+    /**
+     * Records an audit event for the given request and action.
+     * No-op when audit logging is disabled via {@link AuditConfig#isEnabled()}.
+     */
+    public void record(TransportRequest request, AuditAction action) {
+        if (!config.isEnabled()) {
+            return;
+        }
+        auditLog.info("[AUDIT] action={} principal={} timestamp={}",
+            action.name(),
+            extractPrincipal(request),
+            Instant.now().toEpochMilli());
+    }
+
+    /**
+     * Records an audit event with an explicit index target.
+     */
+    public void record(TransportRequest request, AuditAction action, String index) {
+        if (!config.isEnabled()) {
+            return;
+        }
+        auditLog.info("[AUDIT] action={} index={} principal={} timestamp={}",
+            action.name(),
+            index,
+            extractPrincipal(request),
+            Instant.now().toEpochMilli());
+    }
+
+    public void recordBulk(TransportRequest request, AuditAction action, String[] indices) {
+        if (!config.isEnabled() || indices == null || indices.length == 0) { return; }
+        String targets = String.join(",", indices);
+        auditLog.info("[AUDIT] action={} indices={} principal={} timestamp={}",
+            action.name(), targets, extractPrincipal(request), Instant.now().toEpochMilli());
+    }
+
+    public void recordScroll(String scrollId, AuditAction action) {
+        if (!config.isEnabled()) return;
+        int hash = scrollId == null ? 0 : scrollId.hashCode();
+        auditLog.info("[AUDIT] action={} scroll_id_hash={} timestamp={}",
+            action.name(), hash, Instant.now().toEpochMilli());
+    }
+
+    public boolean isEnabled() { return config.isEnabled(); }
+
+    public void flush() { /* synchronous logger -- no-op */ }
+
+    private String extractPrincipal(TransportRequest request) {
+        if (request == null) return "unknown";
+        String ctx = request.getParentTask().toString();
+        return ctx.isEmpty() ? "system" : ctx;
+    }
+}

