@@ -0,0 +1,54 @@
+/*
+ * SPDX-License-Identifier: Apache-2.0
+ */
+package org.opensearch.audit;
+
+import org.opensearch.common.settings.Setting;
+import org.opensearch.common.settings.Settings;
+
+/**
+ * Configuration for audit logging. Reads from cluster/node settings.
+ */
+public class AuditConfig {
+
+    public static final Setting<Boolean> AUDIT_ENABLED_SETTING = Setting.boolSetting(
+        "opensearch.audit.enabled",
+        false,
+        Setting.Property.NodeScope,
+        Setting.Property.Dynamic
+    );
+
+    public static final Setting<Boolean> AUDIT_LOG_REQUEST_BODY = Setting.boolSetting(
+        "opensearch.audit.log_request_body",
+        false,
+        Setting.Property.NodeScope,
+        Setting.Property.Dynamic
+    );
+
+    private final boolean enabled;
+    private final boolean logRequestBody;
+
+    public AuditConfig(boolean enabled, boolean logRequestBody) {
+        this.enabled = enabled;
+        this.logRequestBody = logRequestBody;
+    }
+
+    public static AuditConfig fromSettings(Settings settings) {
+        return new AuditConfig(
+            AUDIT_ENABLED_SETTING.get(settings),
+            AUDIT_LOG_REQUEST_BODY.get(settings)
+        );
+    }
+
+    public boolean isEnabled() { return enabled; }
+    public boolean isLogRequestBody() { return logRequestBody; }
+}

