@@ -0,0 +1,72 @@
+/*
+ * SPDX-License-Identifier: Apache-2.0
+ */
+package org.opensearch.audit;
+
+import org.opensearch.common.settings.Settings;
+import org.opensearch.test.OpenSearchTestCase;
+import org.junit.Before;
+import org.junit.Test;
+
+import static org.mockito.Mockito.*;
+import static org.junit.Assert.*;
+
+public class AuditLoggerTests extends OpenSearchTestCase {
+
+    private AuditLogger auditLogger;
+    private AuditLogger disabledLogger;
+
+    @Before
+    public void setUp() {
+        Settings enabledSettings = Settings.builder()
+            .put(AuditConfig.AUDIT_ENABLED_SETTING.getKey(), true)
+            .build();
+        Settings disabledSettings = Settings.builder()
+            .put(AuditConfig.AUDIT_ENABLED_SETTING.getKey(), false)
+            .build();
+        auditLogger = AuditLogger.fromSettings(enabledSettings);
+        disabledLogger = AuditLogger.fromSettings(disabledSettings);
+    }
+
+    @Test
+    public void testAuditLoggerEnabledByDefault_isFalse() {
+        Settings defaultSettings = Settings.EMPTY;
+        AuditConfig config = AuditConfig.fromSettings(defaultSettings);
+        assertFalse("Audit logging should be disabled by default", config.isEnabled());
+    }
+
+    @Test
+    public void testRecordSearchAction_doesNotThrow() {
+        // record() must be safe to call — no exception even with null request
+        assertDoesNotThrow(() -> auditLogger.record(null, AuditAction.SEARCH));
+    }
+
+    @Test
+    public void testRecordWithIndex_doesNotThrow() {
+        assertDoesNotThrow(() -> auditLogger.record(null, AuditAction.INDEX, "my-index"));
+    }
+
+    @Test
+    public void testDisabledLogger_doesNotLog() {
+        // When disabled, record() should return immediately without logging.
+        // Verify no exception and call completes within 1ms.
+        long start = System.nanoTime();
+        disabledLogger.record(null, AuditAction.BULK);
+        long elapsed = System.nanoTime() - start;
+        assertTrue("Disabled logger should be near-instant", elapsed < 1_000_000);
+    }
+
+    @Test
+    public void testRecordBulk_withMultipleIndices() {
+        String[] indices = {"index-a", "index-b", "index-c"};
+        assertDoesNotThrow(() -> auditLogger.recordBulk(null, AuditAction.BULK, indices));
+    }
+
+    @Test
+    public void testRecordScroll_hashesScrollId() {
+        String scrollId = "FGluY2x1ZGVfY29udGV4dF90cnVlAwAAAAAAAA==";
+        assertDoesNotThrow(() -> auditLogger.recordScroll(scrollId, AuditAction.SEARCH));
+    }
+
+    @Test
+    public void testIsEnabled_reflectsConfig() {
+        assertTrue(auditLogger.isEnabled());
+        assertFalse(disabledLogger.isEnabled());
+    }
+
+    @Test
+    public void testAuditConfig_logRequestBodyEnabled() {
+        Settings s = Settings.builder()
+            .put(AuditConfig.AUDIT_ENABLED_SETTING.getKey(), true)
+            .put(AuditConfig.AUDIT_LOG_REQUEST_BODY.getKey(), true)
+            .build();
+        AuditConfig config = AuditConfig.fromSettings(s);
+        assertTrue(config.isEnabled());
+        assertTrue(config.isLogRequestBody());
+    }
+
+    @Test
+    public void testAuditActionEnum_containsAllExpectedActions() {
+        AuditAction[] actions = AuditAction.values();
+        assertTrue(actions.length >= 10);
+    }
+}

